%Dominykas Janulevičius EDIF-25/1 2026-10-05 12:00
%4 laboratorinis darbas
%%Priv uzd
%%1 a)
[x, y] = meshgrid(linspace(-2, 2, 100));
f = sin(abs(x + y)/20) .* exp(-abs(x + y));

figure; %[output:798623ce]
surf(x, y, f); %[output:798623ce]
colormap(jet); %[output:798623ce]
shading interp; %[output:798623ce]
view(30, 30); %[output:798623ce]
xlabel('x'); ylabel('y'); zlabel('f(x,y)'); %[output:798623ce]
title('f(x,y) = sin(|x+y|/20) \cdot e^{-|x+y|}'); %[output:798623ce]
grid on; %[output:798623ce]

%%1 b)
[r, th] = meshgrid(linspace(0, 1, 40), linspace(0, 2*pi, 80));
x = r.*cos(th);
y = r.*sin(th);
f = 1 - 2*x.^2 - 3*y.^2;

figure; %[output:92c42fac]
surf(x, y, f); %[output:92c42fac]
colormap(parula); %[output:92c42fac]
shading interp; %[output:92c42fac]
view(78, 30); %[output:92c42fac]
xlabel('x'); ylabel('y'); zlabel('f(x,y)'); %[output:92c42fac]
title('f(x,y) = 1 - 2x^2 - 3y^2'); %[output:92c42fac]
grid on; %[output:92c42fac]

%%Pap uzd
%%1
[x, y] = meshgrid(linspace(-1, 1, 60));
z = 1 - (x.^2 + y.^2);

figure; %[output:95162bc8]
surf(x, y, z, 'FaceColor', 'r', 'EdgeColor', 'none'); %[output:95162bc8]
camlight('left'); %[output:95162bc8]
lighting gouraud; %[output:95162bc8]
xlabel('x'); ylabel('y'); zlabel('z'); %[output:95162bc8]
title('z(x,y) = 1 - (x^2 + y^2)'); %[output:95162bc8]
axis tight; grid on; %[output:95162bc8]

